// Playlist-Antwort kann als einzelnes Objekt oder als Array mit einem
// Eintrag zurueckkommen, je nach n8n-/API-Verhalten -- beides abfangen.
const items = $input.all();
let playlist = null;
for (const item of items) {
  if (item.json && Array.isArray(item.json.widgets)) {
    playlist = item.json;
    break;
  }
}
if (!playlist && items.length > 0 && Array.isArray(items[0].json)) {
  playlist = items[0].json.find((p) => Array.isArray(p.widgets));
}
if (!playlist) {
  throw new Error('Playlist "infotafel" nicht gefunden oder ohne widgets -- embed=widgets und Playlist-Name/Permissions pruefen.');
}

const images = (playlist.widgets || [])
  .filter((w) => w.type === 'image')
  .sort((a, b) => (a.displayOrder ?? 0) - (b.displayOrder ?? 0))
  .map((w, idx) => ({
    mediaId: Array.isArray(w.mediaIds) ? w.mediaIds[0] : w.mediaId,
    order: String(idx + 1).padStart(3, '0'),
  }));

if (images.length === 0) {
  return [];
}

return images.map((img) => ({ json: img }));

const order = $('Bild-Widgets extrahieren & sortieren').item.json.order;
const mediaId = $('Bild-Widgets extrahieren & sortieren').item.json.mediaId;
const meta = $('Medien-Metadaten holen').item.json;
const metaObj = Array.isArray(meta) ? meta[0] : meta;
const originalName = (metaObj && metaObj.fileName) || `${mediaId}.jpg`;
const extMatch = originalName.match(/\.[a-zA-Z0-9]+$/);
const ext = extMatch ? extMatch[0].toLowerCase() : '.jpg';
const fileName = `xibo-playlist-${order}-${mediaId}${ext}`;

$input.item.json.outputPath = `/data/xibosignage-display/${fileName}`;
$input.item.json.expectedFileName = fileName;

return $input.item;

// Loescht alte xibo-playlist-*-Dateien aus dem Display-Ordner, die in
// diesem Lauf NICHT (mehr) aus der Playlist synchronisiert wurden --
// z.B. weil ein Bild aus der Xibo-Playlist entfernt wurde. Nutzt direkten
// fs-Zugriff auf den bereits im n8n-Pod gemounteten Ordner (siehe
// argocd/apps/workloads/n8n/values.yaml -> xibosignage.display), analog
// zum bereits vorhandenen require('path') im Inbox-Workflow --
// Node-Builtins sind in diesem n8n Code-Node bereits erlaubt.
const fs = require('fs');
const path = require('path');
const dir = '/data/xibosignage-display';

const expected = new Set($input.all().map((item) => item.json.expectedFileName));

const existing = fs.readdirSync(dir).filter((f) => f.startsWith('xibo-playlist-'));
const removed = [];
for (const f of existing) {
  if (!expected.has(f)) {
    fs.unlinkSync(path.join(dir, f));
    removed.push(f);
  }
}

return [{ json: { synced: [...expected], removed } }];
